import { Table, ReferenceColumn, StringColumn } from '../../db'

export const sys_security_acl_role = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    label: 'Access Roles',
    name: 'sys_security_acl_role',
    schema: {
        sys_user_role: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Role',
            referenceTable: 'sys_user_role',
        }),
        transaction_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                loader_exempt: true,
                saver_exempt: 'exempt_always',
            },
            label: 'Transaction ID',
        }),
        sys_security_acl: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'ACL',
            referenceTable: 'sys_security_acl',
        }),
    },
    textIndex: true,
})
